/**
 * Period arithmetic, charges and invoice issuance shared by the billing
 * service and the renewal job.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval, Invoice, PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * The end of a period starting at `start`: same day-of-month and time a month
 * (or a year) later, clamped to the target month's last day.
 */
export function periodEndFrom(start: Date, interval: BillingInterval): Date {
  const months = monthsIn(interval);
  const year = start.getUTCFullYear();
  const month = start.getUTCMonth() + months;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  return new Date(
    Date.UTC(
      year,
      month,
      Math.min(start.getUTCDate(), lastDay),
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** Full charge for one period of `plan` at `seats`, in cents. */
export function fullPeriodCharge(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsIn(interval);
}

/** Scales a full-period amount by the days left in the period, rounded down. */
export function prorate(
  fullAmountCents: number,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  now: Date,
): number {
  const start = new Date(periodStart).getTime();
  const end = new Date(periodEnd).getTime();
  const remainingMs = end - now.getTime();
  const daysLeft = remainingMs > 0 ? Math.ceil(remainingMs / MS_PER_DAY) : 0;
  const daysInPeriod = Math.max(1, Math.round((end - start) / MS_PER_DAY));
  return Math.floor((fullAmountCents * daysLeft) / daysInPeriod);
}

/** Persists an invoice and announces it on the bus. */
export async function issueInvoice(
  orgId: OrgId,
  input: {
    amountCents: number;
    periodStart: IsoTimestamp;
    periodEnd: IsoTimestamp;
    actorId: UserId | null;
    now: Date;
  },
): Promise<Invoice | null> {
  if (input.amountCents <= 0) return null;

  const sequence = (await invoiceRepo.countInvoices(orgId)) + 1;
  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number: `INV-${String(sequence).padStart(6, "0")}`,
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId: input.actorId,
    occurredAt: toIsoTimestamp(input.now),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}
