/**
 * Renews subscriptions whose period has ended, invoicing each paid period,
 * and ends cancellations that have reached their date.
 *
 * Must call (do not reimplement): emit, issueInvoice
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import {
  fullPeriodCharge,
  issueInvoice,
  periodEndFrom,
} from "@/server/services/billing-invoicing";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * Replay-safe by construction: every step moves the period end (or clears the
 * cancellation) past `now`, so a second run at the same instant finds nothing.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsOfLiveOrgs();

    for (const subscription of subscriptions) {
      try {
        const changed = await settle(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function settle(subscription: Subscription, now: Date): Promise<boolean> {
  const orgId = subscription.orgId as OrgId;
  let current = subscription;
  let changed = false;

  if (current.status === "canceled") {
    if (current.cancelAt === null || new Date(current.cancelAt) > now) {
      return false;
    }

    const start = new Date(current.cancelAt);
    current = await subscriptionRepo.updateSubscriptionState(orgId, {
      plan: FALLBACK_PLAN,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: toIsoTimestamp(start),
      currentPeriodEnd: toIsoTimestamp(periodEndFrom(start, "monthly")),
    });

    await emit("billing.plan_changed", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from: subscription.plan,
      to: FALLBACK_PLAN,
    });
    changed = true;
  }

  if (current.status !== "active") return changed;

  while (new Date(current.currentPeriodEnd) <= now) {
    const start = new Date(current.currentPeriodEnd);
    const end = periodEndFrom(start, current.interval);

    current = await subscriptionRepo.updateSubscriptionState(orgId, {
      currentPeriodStart: toIsoTimestamp(start),
      currentPeriodEnd: toIsoTimestamp(end),
    });

    await issueInvoice(orgId, {
      amountCents: fullPeriodCharge(current.plan, current.seats, current.interval),
      periodStart: current.currentPeriodStart,
      periodEnd: current.currentPeriodEnd,
      actorId: null,
      now,
    });
    changed = true;
  }

  return changed;
}
